#!/bin/bash
FILE="src/main/java/com/example/MainActivity.kt"

# Add imports
perl -i -pe 's/(import androidx.compose.material3.Text)/$1\nimport androidx.compose.material3.DropdownMenu\nimport androidx.compose.material3.DropdownMenuItem\nimport androidx.compose.material.icons.rounded.MoreVert/g' "$FILE"

# Add state variable
perl -i -pe 's/(var showAddDialog.*)/$1\n                var showSettingsMenu by remember { mutableStateOf(false) }/g' "$FILE"

# Replace actions block
perl -i -0777 -pe 's/actions = \{[\s\S]*?\},[^c]*colors = TopAppBarDefaults/actions = {\n                                        Box {\n                                            IconButton(onClick = { showSettingsMenu = true }) {\n                                                Icon(\n                                                    imageVector = Icons.Rounded.MoreVert,\n                                                    contentDescription = "Pengaturan",\n                                                    tint = MaterialTheme.colorScheme.onSurface\n                                                )\n                                            }\n                                            DropdownMenu(\n                                                expanded = showSettingsMenu,\n                                                onDismissRequest = { showSettingsMenu = false }\n                                            ) {\n                                                DropdownMenuItem(\n                                                    text = { Text(if (isDarkMode) "Mode Terang" else "Mode Gelap") },\n                                                    onClick = { \n                                                        isDarkMode = !isDarkMode\n                                                        prefs.edit().putBoolean("is_dark_mode", isDarkMode).apply()\n                                                        showSettingsMenu = false\n                                                    },\n                                                    leadingIcon = {\n                                                        Icon(\n                                                            imageVector = if (isDarkMode) Icons.Rounded.LightMode else Icons.Rounded.DarkMode,\n                                                            contentDescription = null\n                                                        )\n                                                    }\n                                                )\n                                                DropdownMenuItem(\n                                                    text = { Text("Hapus Semua Data") },\n                                                    onClick = { \n                                                        viewModel.clearAllData()\n                                                        showSettingsMenu = false\n                                                    },\n                                                    leadingIcon = {\n                                                        Icon(\n                                                            imageVector = Icons.Rounded.Delete,\n                                                            contentDescription = null\n                                                        )\n                                                    }\n                                                )\n                                                DropdownMenuItem(\n                                                    text = { Text("Logout (" + (userName ?: "User") + ")") },\n                                                    onClick = { \n                                                        prefs.edit().clear().apply()\n                                                        workspacePin = null\n                                                        userName = null\n                                                        showSettingsMenu = false\n                                                    },\n                                                    leadingIcon = {\n                                                        Icon(\n                                                            imageVector = Icons.Rounded.ExitToApp,\n                                                            contentDescription = null\n                                                        )\n                                                    }\n                                                )\n                                            }\n                                        }\n                                    },\n                                    colors = TopAppBarDefaults/g' "$FILE"

